# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
npm install dotenv  # for environment variables
```

## Basic Pool Configuration

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT) || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                    // Maximum connections in pool
  min: 2,                     // Minimum connections to maintain
  idleTimeoutMillis: 30000,   // Close idle connections after 30s
  connectionTimeoutMillis: 5000, // Fail if connection takes > 5s
  maxUses: 7500,              // Retire connection after 7500 queries (prevents memory leaks)

  // SSL configuration (for production)
  ssl: process.env.NODE_ENV === 'production' 
    ? { rejectUnauthorized: true, ca: process.env.DB_SSL_CERT }
    : false,
});

module.exports = pool;
```

## Error Handling Setup

```javascript
// db/pool.js (continued)

// Handle idle client errors (network issues, server restarts)
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client:', err.message);
  // Don't crash the process - log and continue
  // Consider alerting your monitoring system here
});

// Optional: Log pool events for debugging
pool.on('connect', (client) => {
  console.log(`New client connected. Pool size: ${pool.totalCount}`);
});

pool.on('acquire', (client) => {
  console.log(`Client acquired. Idle: ${pool.idleCount}, Total: ${pool.totalCount}`);
});

pool.on('remove', (client) => {
  console.log(`Client removed. Pool size: ${pool.totalCount}`);
});
```

## Query Wrapper with Error Handling

```javascript
// db/query.js
const pool = require('./pool');

/**
 * Execute a query using a pool client
 * Handles timeouts, retries, and proper client release
 */
async function query(text, params, options = {}) {
  const { timeout = 10000, retries = 1 } = options;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    const client = await pool.connect().catch(err => {
      throw new DatabaseError('Failed to acquire connection', err);
    });

    // Set statement timeout per query
    const timeoutQuery = `SET statement_timeout = ${timeout}`;

    try {
      await client.query(timeoutQuery);

      const start = Date.now();
      const result = await client.query(text, params);
      const duration = Date.now() - start;

      // Log slow queries
      if (duration > 1000) {
        console.warn('Slow query detected:', {
          text: text.substring(0, 100),
          duration,
          rows: result.rowCount,
        });
      }

      return result;
    } catch (err) {
      lastError = err;

      // Only retry on connection errors, not query errors
      const isConnectionError = err.code === 'ECONNRESET' || 
                                err.code === 'EPIPE' ||
                                err.message.includes('connection');

      if (!isConnectionError || attempt === retries) {
        throw new DatabaseError(err.message, err, text);
      }

      console.warn(`Query attempt ${attempt + 1} failed, retrying...`);
      await sleep(100 * (attempt + 1)); // Exponential backoff
    } finally {
      client.release(); // Always release - even on error
    }
  }

  throw lastError;
}

/**
 * Execute multiple queries in a transaction
 */
async function transaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Custom error class for better error context
class DatabaseError extends Error {
  constructor(message, originalError, query) {
    super(message);
    this.name = 'DatabaseError';
    this.code = originalError?.code;
    this.query = query;
    this.originalError = originalError;
  }
}

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

module.exports = { query, transaction, DatabaseError };
```

## Health Check & Monitoring

```javascript
// db/health.js
const pool = require('./pool');

async function checkDatabaseHealth() {
  const start = Date.now();

  try {
    await pool.query('SELECT 1');
    return {
      status: 'healthy',
      latencyMs: Date.now() - start,
      pool: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    };
  } catch (err) {
    return {
      status: 'unhealthy',
      error: err.message,
      pool: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    };
  }
}

module.exports = { checkDatabaseHealth };
```

## Graceful Shutdown

```javascript
// db/shutdown.js
const pool = require('./pool');

async function gracefulShutdown(signal) {
  console.log(`Received ${signal}, closing database pool...`);

  try {
    await pool.end(); // Waits for active queries to complete
    console.log('Database pool closed successfully');
  } catch (err) {
    console.error('Error closing database pool:', err);
    process.exit(1);
  }
}

process.on('SIGINT', () => gracefulShutdown('SIGINT'));
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
```

## Usage Examples

```javascript
// routes/users.js
const { query, transaction } = require('../db/query');

// Simple query
async function getUser(id) {
  const result = await query(
    'SELECT * FROM users WHERE id = $1',
    [id],
    { timeout: 5000 }
  );
  return result.rows[0];
}

// Transaction example
async function transferFunds(fromId, toId, amount) {
  return transaction(async (client) => {
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );
    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );
    const result = await client.query(
      'INSERT INTO transfers (from_id, to_id, amount) VALUES ($1, $2, $3) RETURNING *',
      [fromId, toId, amount]
    );
    return result.rows[0];
  });
}
```

## Environment Variables (.env)

```bash
DB_HOST=localhost
DB_PORT=5432
DB_NAME=myapp
DB_USER=myuser
DB_PASSWORD=mypassword
NODE_ENV=development
```

## Key Configuration Guidelines

| Setting | Development | Production |
|---|---|---|
| `max` | 5-10 | 10-25 (tune based on DB limits) |
| `idleTimeoutMillis` | 10000 | 30000 |
| `connectionTimeoutMillis` | 3000 | 5000 |
| `statement_timeout` | 30000 | 10000 |
| SSL | false | true |

**Critical rules to remember:**
- Always release clients in a `finally` block
- Never exceed your database's `max_connections` limit (check with `SHOW max_connections`)
- Set `max` pool size to `(max_connections - superuser_reserved) / num_app_instances`
- Monitor `pool.waitingCount` — if consistently > 0, increase pool size or optimize queries
